	/**
	 * 保持するコンテナのListを返します。
	 *
	 * @return コンテナのList
	 */
	public List<MCContainer> getContainers(){
		List<MCContainer> ret = super.getContainers();
		if(!MCCollectionUtil.contains(ret, getCndR())) ret.add(getCndR());
		if(!MCCollectionUtil.contains(ret, getHdrR())) ret.add(getHdrR());
		if(!MCCollectionUtil.contains(ret, getDtlOperL())) ret.add(getDtlOperL());
		if(!MCCollectionUtil.contains(ret, getOperBtnR())) ret.add(getOperBtnR());
		if(!MCCollectionUtil.contains(ret, getDtlYieldL())) ret.add(getDtlYieldL());
		if(!MCCollectionUtil.contains(ret, getYieldBtnR())) ret.add(getYieldBtnR());
		if(!MCCollectionUtil.contains(ret, getDtlByProdL())) ret.add(getDtlByProdL());
		if(!MCCollectionUtil.contains(ret, getByProdBtnR())) ret.add(getByProdBtnR());
		if(!MCCollectionUtil.contains(ret, getDtlArrActL())) ret.add(getDtlArrActL());
		if(!MCCollectionUtil.contains(ret, getDtlInptL())) ret.add(getDtlInptL());
		if(!MCCollectionUtil.contains(ret, getDtlLossL())) ret.add(getDtlLossL());
		if(!MCCollectionUtil.contains(ret, getInptBtnR())) ret.add(getInptBtnR());
		if(!MCCollectionUtil.contains(ret, getDtlWkL())) ret.add(getDtlWkL());
		if(!MCCollectionUtil.contains(ret, getWkBtnR())) ret.add(getWkBtnR());
		if(!MCCollectionUtil.contains(ret, getBtnR())) ret.add(getBtnR());
		return ret;
	}

	/**
	 * コンテナに対応したブロックのIDを返します。
	 *
	 * 引数のコンテナに対応するブロックがない場合にはnullを返します。<br>
	 * 引数がnullの場合にはnullを返します。<br>
	 *
	 * @return ブロックID
	 */
	public String getBlockId(MCContainer aCnt){
		if(aCnt == null) return null;
		if(aCnt == getCndR()) return "Cnd";
		if(aCnt == getHdrR()) return "Hdr";
		if(aCnt == getDtlOperL()) return "DtlOper";
		if(aCnt == getOperBtnR()) return "OperBtn";
		if(aCnt == getDtlYieldL()) return "DtlYield";
		if(aCnt == getYieldBtnR()) return "YieldBtn";
		if(aCnt == getDtlByProdL()) return "DtlByProd";
		if(aCnt == getByProdBtnR()) return "ByProdBtn";
		if(aCnt == getDtlArrActL()) return "DtlArrAct";
		if(aCnt == getDtlInptL()) return "DtlInpt";
		if(aCnt == getDtlLossL()) return "DtlLoss";
		if(aCnt == getInptBtnR()) return "InptBtn";
		if(aCnt == getDtlWkL()) return "DtlWk";
		if(aCnt == getWkBtnR()) return "WkBtn";
		if(aCnt == getBtnR()) return "Btn";
		return super.getBlockId(aCnt);
	}

	/**
	 * ブロックIDに対応したコンテナを返します。
	 *
	 * 引数のブロックIDに対応するブロックがない場合にはnullを返します。<br>
	 * 引数がnullの場合にはnullを返します。<br>
	 *
	 * @return コンテナ
	 */
	public MCContainer getContainer(String bId){
		if(bId == null) return null;
		if(bId.equals("Cnd")) return getCndR();
		if(bId.equals("Hdr")) return getHdrR();
		if(bId.equals("DtlOper")) return getDtlOperL();
		if(bId.equals("OperBtn")) return getOperBtnR();
		if(bId.equals("DtlYield")) return getDtlYieldL();
		if(bId.equals("YieldBtn")) return getYieldBtnR();
		if(bId.equals("DtlByProd")) return getDtlByProdL();
		if(bId.equals("ByProdBtn")) return getByProdBtnR();
		if(bId.equals("DtlArrAct")) return getDtlArrActL();
		if(bId.equals("DtlInpt")) return getDtlInptL();
		if(bId.equals("DtlLoss")) return getDtlLossL();
		if(bId.equals("InptBtn")) return getInptBtnR();
		if(bId.equals("DtlWk")) return getDtlWkL();
		if(bId.equals("WkBtn")) return getWkBtnR();
		if(bId.equals("Btn")) return getBtnR();
		return super.getContainer(bId);
	}

	/**
	 * 保持するPanel(枠)のListを返します。
	 *
	 * @return MCPanelのList
	 */
	public List<MCPanel> getMCPanels(){
		List<MCPanel> ret = super.getMCPanels();
		ret.add(ScreenOpePanel);
		ret.add(CndPanel);
		ret.add(HdrPanelPanel);
		ret.add(HdrTabPanel);
		ret.add(HdrPanel);
		ret.add(SystemInfoPanel);
		ret.add(AprvPanel);
		ret.add(AprvItmPanel);
		ret.add(AprvBtnPanel);
		ret.add(AprvEastBtnPanel);
		ret.add(OperTabPanel);
		ret.add(OperPanelPanel);
		ret.add(DtlOperPanel);
		ret.add(OperBtnPanel);
		ret.add(DtlTab1Panel);
		ret.add(YieldPanelPanel);
		ret.add(DtlYieldPanel);
		ret.add(YieldBtnPanel);
		ret.add(ByProdPanelPanel);
		ret.add(DtlByProdPanel);
		ret.add(ByProdBtnPanel);
		ret.add(ArrActPanelPanel);
		ret.add(DtlArrActPanel);
		ret.add(DtlTab2Panel);
		ret.add(InptPanelPanel);
		ret.add(DtlInptPanel);
		ret.add(InptBtnPanel);
		ret.add(WkPanelPanel);
		ret.add(DtlWkPanel);
		ret.add(WkBtnPanel);
		ret.add(BtnPanel);
		ret.add(EastBtnPanel);
		return ret;
	}

