	/**
	 * コンストラクタです。埋込カラムとして作成するときに使用します。
	 *
	 * @param name 対応するInnerRow項目名
	 */
	public MSBCP_MfgActReg_MC_A(String name) {
		aCndR = createCndR();
		aHdrR = createHdrR();
		aDtlOperL = createDtlOperL();
		createDtlOperTable();
		DtlOperTable.setRowName(name);
		aOperBtnR = createOperBtnR();
		aDtlYieldL = createDtlYieldL();
		createDtlYieldTable();
		DtlYieldTable.setRowName(name);
		aYieldBtnR = createYieldBtnR();
		aDtlByProdL = createDtlByProdL();
		createDtlByProdTable();
		DtlByProdTable.setRowName(name);
		aByProdBtnR = createByProdBtnR();
		aDtlArrActL = createDtlArrActL();
		createDtlArrActTable();
		DtlArrActTable.setRowName(name);
		aDtlInptL = createDtlInptL();
		createDtlInptTable();
		DtlInptTable.setRowName(name);
		aDtlLossL = createDtlLossL();
		aInptBtnR = createInptBtnR();
		aDtlWkL = createDtlWkL();
		createDtlWkTable();
		DtlWkTable.setRowName(name);
		aWkBtnR = createWkBtnR();
		aBtnR = createBtnR();
	}


	/**
	 * 埋め込み画面Fieldとエイリアス定義されたGUI部品Fieldの初期化を行います。
	 */
