	/**
	 * この画面のステータスを設定します。
	 *
	 * @param status ステータス
	 */
	public void setStatus(String status) {
		super.setStatus(status);
		if (SRCH_INS.equals(status)) {
			setSRCH_INSStatus();
		}
		else if (INS_ACT.equals(status)) {
			setINS_ACTStatus();
		}
		else if (UPD_ACT.equals(status)) {
			setUPD_ACTStatus();
		}
		else if (DEL_ACT.equals(status)) {
			setDEL_ACTStatus();
		}
		else if (UPD_APRV.equals(status)) {
			setUPD_APRVStatus();
		}
		else if (DEL_APRV.equals(status)) {
			setDEL_APRVStatus();
		}
		else if (SRCH.equals(status)) {
			setSRCHStatus();
		}
		else if (REF.equals(status)) {
			setREFStatus();
		}
		else if (FIX_I.equals(status)) {
			setFIX_IStatus();
		}
		else if (FIX_U.equals(status)) {
			setFIX_UStatus();
		}
		else if (FIX_D.equals(status)) {
			setFIX_DStatus();
		}
		else if (FIX_APRV.equals(status)) {
			setFIX_APRVStatus();
		}
	}

