	public void doAPEvent(MCAPBeans ap, MCEventInfo info) {
		super.doAPEvent(ap, info);
		if (ap == Cnd_srch) doCnd_srch(info);
		else if (ap == Hdr_st_re_calc) doHdr_st_re_calc(info);
		else if (ap == OperBtn_sprt_inpt_recalc) doOperBtn_sprt_inpt_recalc(info);
		else if (ap == OperBtn_sprt_wk_recalc) doOperBtn_sprt_wk_recalc(info);
		else if (ap == OperBtn_select_all) doOperBtn_select_all(info);
		else if (ap == OperBtn_deselect_all) doOperBtn_deselect_all(info);
		else if (ap == OperBtn_rdel) doOperBtn_rdel(info);
		else if (ap == OperBtn_rcopy) doOperBtn_rcopy(info);
		else if (ap == YieldBtn_sprt_lot_no) doYieldBtn_sprt_lot_no(info);
		else if (ap == YieldBtn_select_all) doYieldBtn_select_all(info);
		else if (ap == YieldBtn_deselect_all) doYieldBtn_deselect_all(info);
		else if (ap == YieldBtn_rdel) doYieldBtn_rdel(info);
		else if (ap == YieldBtn_rcopy) doYieldBtn_rcopy(info);
		else if (ap == ByProdBtn_sprt_lot_no) doByProdBtn_sprt_lot_no(info);
		else if (ap == ByProdBtn_select_all) doByProdBtn_select_all(info);
		else if (ap == ByProdBtn_deselect_all) doByProdBtn_deselect_all(info);
		else if (ap == ByProdBtn_radd) doByProdBtn_radd(info);
		else if (ap == ByProdBtn_rdel) doByProdBtn_rdel(info);
		else if (ap == ByProdBtn_rcopy) doByProdBtn_rcopy(info);
		else if (ap == InptBtn_open_MSBEP2520) doInptBtn_open_MSBEP2520(info);
		else if (ap == InptBtn_open_MSBCP1120) doInptBtn_open_MSBCP1120(info);
		else if (ap == InptBtn_sprt_lot_prop) doInptBtn_sprt_lot_prop(info);
		else if (ap == InptBtn_select_all) doInptBtn_select_all(info);
		else if (ap == InptBtn_deselect_all) doInptBtn_deselect_all(info);
		else if (ap == InptBtn_radd) doInptBtn_radd(info);
		else if (ap == InptBtn_rdel) doInptBtn_rdel(info);
		else if (ap == InptBtn_rcopy) doInptBtn_rcopy(info);
		else if (ap == WkBtn_select_all) doWkBtn_select_all(info);
		else if (ap == WkBtn_deselect_all) doWkBtn_deselect_all(info);
		else if (ap == WkBtn_radd) doWkBtn_radd(info);
		else if (ap == WkBtn_rdel) doWkBtn_rdel(info);
		else if (ap == WkBtn_rcopy) doWkBtn_rcopy(info);
		else if (ap == Btn_open_MSBFP0110) doBtn_open_MSBFP0110(info);
		else if (ap == Btn_open_MSBCP1010) doBtn_open_MSBCP1010(info);
		else if (ap == Btn_prnt_act) doBtn_prnt_act(info);
		else if (ap == Btn_open_MSBEP0110) doBtn_open_MSBEP0110(info);
		else if (ap == Btn_upd) doBtn_upd(info);
		else if (ap == Btn_del) doBtn_del(info);
		else if (ap == Btn_upd_aprv) doBtn_upd_aprv(info);
		else if (ap == Btn_del_aprv) doBtn_del_aprv(info);
	}

